// Exact text first, so an uppercase label (RETURN, a noun) and a button (Return, a verb) keep their own rows;
// otherwise any capitalisation of a known phrase. An all-caps label stays all caps in every language.
const exact = new Map(rows.map(row => [row[0] ?? '', row]));
const dictionary = new Map<string, string[]>();
for (const row of rows) { const key = (row[0] ?? '').toLowerCase(); if (!dictionary.has(key)) dictionary.set(key, row); }
const lookup = (text: string, lang: Lang) => {
  // English is the source language: a label reads exactly as the screen wrote it ("Low Stock", "Business name"), never in the
  // capitalisation of whichever dictionary row it happens to match. The other languages still match any capitalisation.
  if (lang === 'English') return text;
  const i = LANGS.indexOf(lang);
  const hit = exact.get(text)?.[i];
  if (hit !== undefined) return hit;
  const found = dictionary.get(text.toLowerCase())?.[i];
  if (found === undefined) return undefined;
  return /[a-z]/.test(text) || !/[A-Z]/.test(text) ? found : found.toLocaleUpperCase();
};
export function translateText(lang: Lang, text: string, x?: string | number) {
  if (typeof text !== 'string' || !text) return '';
  const patterns: [RegExp, string, string[]][] = [
    [/^Not enough stock for (.+) \(available (.+)\)$/, 'Not enough stock for {name} (available {qty})', ['name', 'qty']],
    [/^Insufficient stock: (.+) \(available (.+)\)$/, 'Insufficient stock: {name} (available {qty})', ['name', 'qty']],
    [/^Invalid quantity for (.+)$/, 'Invalid quantity for {name}', ['name']],
    [/^Only (.+) of (.+) can be returned$/, 'Only {qty} of {name} can be returned', ['qty', 'name']],
  ];
  for (const [pattern, key, fields] of patterns) {
    const match = text.match(pattern);
    if (match) { let value = lookup(key, lang) ?? key; fields.forEach((field, index) => { value = value.replace(`{${field}}`, match[index + 1] ?? ''); }); return value; }
  }
  const translated = lookup(text, lang) ?? text;
  return x === undefined ? translated : translated.replace('{x}', String(x));
}

// For the page-wide translator (dom-translate.ts): the translation of a known English phrase, or undefined
// when the phrase isn't in the dictionary, so names, numbers and typed records are never touched.
export function knownTranslation(lang: Lang, text: string): string | undefined {
  if (lang === 'English' || !text) return undefined;
  const hit = lookup(text, lang);
  return hit !== undefined && hit !== text ? hit : undefined;
}

// Text a screen already translated with tr() must not be read again as English ("Data" is Portuguese for Date).
const shownIn = new Map<Lang, Set<string>>();
export function isTranslatedText(lang: Lang, text: string) {
  let set = shownIn.get(lang);
  if (!set) {
    const i = LANGS.indexOf(lang);
    set = new Set<string>();
    for (const row of rows) { const v = row[i]; if (v && v !== row[0]) { set.add(v); set.add(v.toLocaleUpperCase()); } }
    shownIn.set(lang, set);
  }
  return set.has(text);
}

export function translateCurrent(text: string) {
  const saved = typeof window === 'undefined' ? 'English' : localStorage.getItem('shopbook.language');
  const lang = LANGS.find(l => l === saved) ?? 'English';
  return translateText(lang, text);
}
